def summ(atoms):
    b=atoms.bonds.as_array().astype(int) if atoms.bonds is not None else np.empty((0,3),int)
    bad=0
    if len(b):
        bad=np.sum((b[:,0]>=atoms.array_length())|(b[:,1]>=atoms.array_length())|(b[:,0]<0)|(b[:,1]<0))
